function mPath(c,pts,fill,stroke,width=2,close=true){if(!pts.length)return;c.beginPath();pts.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));if(close)c.closePath();if(fill){c.fillStyle=fill;c.fill()}if(stroke){c.strokeStyle=stroke;c.lineWidth=width;c.stroke()}}
function mArc(c,x,y,r,a,b,col,w=5){c.beginPath();c.arc(x,y,Math.max(1,r),a,b);c.strokeStyle=col;c.lineWidth=w;c.lineCap='round';c.stroke()}
function mArrow(c,x1,y1,x2,y2,col,w=8){line(c,x1,y1,x2,y2,col,w);let a=Math.atan2(y2-y1,x2-x1),len=Math.max(16,w*2.2);mPath(c,[[x2,y2],[x2-Math.cos(a-.45)*len,y2-Math.sin(a-.45)*len],[x2-Math.cos(a+.45)*len,y2-Math.sin(a+.45)*len]],col)}
function mCoin(c,x,y,w,h,color,edge=p=>p){c.save();c.fillStyle=color;c.beginPath();c.ellipse(x,y,w,h*.24,0,0,Math.PI*2);c.fill();rr(c,x-w,y,w*2,h*.52,h*.06,color);c.strokeStyle='rgba(255,255,255,.22)';c.lineWidth=2;c.beginPath();c.ellipse(x,y+h*.52,w,h*.25,0,0,Math.PI);c.stroke();c.restore()}
function mPaper(c,x,y,w,h,p,shadow=true){c.save();if(shadow){c.shadowBlur=35;c.shadowColor='rgba(0,0,0,.38)'}rr(c,x,y,w,h,15,'#eee9db','#d4d0c6',3);c.restore();rr(c,x+22,y+26,Math.min(100,w*.33),8,4,p.hot);for(let i=0;i<6;i++)rr(c,x+24,y+55+i*24,Math.max(14,w-55-(i%3)*21),5,2,'#c8c5b8')}
function mGlow(c,x,y,r,color,alpha=.16){glow(c,x,y,r,color,alpha)}
function mLabel(c,s,key,box,sz,color,idx,thumb,opt={}){return textBox(c,s,key,box,sz,color,{index:idx,thumbnail:thumb,lines:2,...opt})}
function mRegion(d){const l=layout(d);return {v:l.v,sq:l.sq,x:l.pad,y:l.top,w:d.w-2*l.pad,h:l.bottom-l.top};}
function mLabelBox(c,s,key,x,y,w,h,fontSize,color,idx,thumb,opt={}){return mLabel(c,s,key,{x,y,w,h},fontSize,color,idx,thumb,opt)}
function mPie(c,cx,cy,r,part,start,col,width){mArc(c,cx,cy,r,start,start+Math.PI*2*part,col,width)}
function mPulse(c,x,y,r,col,t){for(let j=0;j<3;j++){let rr0=r*(.53+(t+j*.29)%1);mArc(c,x,y,rr0,0,Math.PI*2,rgba(col,.46*(1-(t+j*.29)%1)),3)}}
