function setRatio(ratio){if(!['landscape','portrait','square'].includes(ratio))return;state.ratio=ratio;const sizes={landscape:[1920,1080],portrait:[1080,1920],square:[1080,1080]};[cv.width,cv.height]=sizes[ratio];cv.style.aspectRatio=ratio==='landscape'?'16 / 9':ratio==='portrait'?'9 / 16':'1 / 1';$('resolution').textContent=cv.width+' × '+cv.height;document.querySelectorAll('[data-ratio]').forEach(b=>b.classList.toggle('active',b.dataset.ratio===ratio));renderFrame()}
