function v8Ambient(c,idx,time,canvasObj,opts={}){
 const fx=state.atmosphere||'none';if(fx==='none')return;
 const ratio=opts.forceRatio||state.ratio,d=dim(ratio),w=d.w,h=d.h,p=T(),t=time,st=clamp((state.fxStrength||65)/100),q=t*Math.PI*2;
 c.save();c.setTransform(canvasObj.width/w,0,0,canvasObj.height/h,0,0);
 if(fx==='stardust'){
  for(let j=0;j<100;j++){let x=(v8N(j+101)*w+Math.sin(q+j)*w*.016+w)%w,y=(v8N(j+81)*h+t*h*(.04+v8N(j+93)*.12))%h;v8Point(c,x,y,(1+v8N(j+5)*3)*st,rgba(j%3?p.main:p.alt,(.12+v8N(j+12)*.45)*st))}
 }else if(fx==='light'){
  let x=(t*1.5-.3)*w;const g=c.createLinearGradient(x-130,0,x+130,0);g.addColorStop(0,rgba(p.main,0));g.addColorStop(.48,rgba(p.main,.13*st));g.addColorStop(.5,'rgba(255,255,255,'+(.16*st)+')');g.addColorStop(1,rgba(p.main,0));c.fillStyle=g;c.fillRect(x-130,0,260,h);
 }else if(fx==='film'){
  for(let j=0;j<100;j++){let x=v8N(j*2+201)*w,y=v8N(j*3+202)*h,v=v8N(j+211);v8Point(c,x,y,(.8+v*1.6)*st,'rgba(255,255,255,'+(.035*st)+')')}
  for(let j=0;j<4;j++){let y=((j*.26+t*.14)%1)*h;v8Line(c,0,y,w,y,rgba(p.text,.038*st),1)}
 }else if(fx==='electric'){
  for(let j=0;j<21;j++){const a=j*2.399+q*.29,x=w*(.5+.45*Math.cos(a)),y=h*(.52+.42*Math.sin(a)),len=25+35*v8N(j+72);v8Line(c,x,y,x+len*Math.cos(a+.9),y+len*Math.sin(a+.9),rgba(j%2?p.main:p.alt,.4*st),2)}
 }else if(fx==='scanlines'){
  for(let y=0;y<h;y+=7){v8Line(c,0,y,w,y,rgba(p.text,.045*st),1)}let scan=(t%1)*h;v8Line(c,0,scan,w,scan,rgba(p.main,.6*st),3)
 }
 c.restore();
}
