const v8Observer=typeof IntersectionObserver!=='undefined'?new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;const id=entry.target?.id;const index=Number(id?.replace('thumb-',''));v8Observer.unobserve(entry.target);if(Number.isInteger(index)&&id==='thumb-'+index)renderThumb(index)}},{root:document.querySelector('.library'),rootMargin:'200px 80px'}):null;
function lazySceneThumb(i){const target=$('thumb-'+i);if(!target)return;if(v8Observer)v8Observer.observe(target);else renderThumb(i)}

const v8PreviousRender=renderScene;
renderScene=function(c,idx,time,canvasObj=cv,opts={}){
 const id=SCENES[idx]?.id;const t=clamp(time*state.speed);
 window.__studioTime=t;
 if(V8_IDS.has(id))v8DrawScene(c,idx,t,canvasObj,opts);else v8PreviousRender(c,idx,time,canvasObj,opts);
 v8Ambient(c,idx,t,canvasObj,opts);
};
function v8Number(raw,tm){
 const match=String(raw).match(/^(\D*?)(-?\d[\d,]*(?:\.\d+)?)([\s\S]*)$/);if(!match)return String(raw);
 const number=Number(match[2].replaceAll(',',''));if(!Number.isFinite(number))return String(raw);
 const decimal=(match[2].split('.')[1]||'').length;
 const value=number*enter(tm,.07,.68);
 return match[1]+value.toLocaleString('en-IN',{minimumFractionDigits:decimal,maximumFractionDigits:decimal})+match[3];
}

