async function exportMP4(){
 if(state.recording)return;
 if(!('VideoEncoder' in window)||!('VideoFrame' in window)){
   info('MP4 requires WebCodecs (recent Chrome or Edge over HTTPS or localhost). Use WebM otherwise.');return;
 }
 const btn=document.getElementById('exportMP4');
 let encoder, muxer, track;
 const previous={playing:state.playing,t:state.t};
 state.playing=false;state.recording=true;btn.disabled=true;
 try{
   info('Loading MP4 muxer…');
   const lib=await import('https://cdn.jsdelivr.net/npm/mp4-muxer@5.2.2/+esm');
   const fps=Number(document.getElementById('fps').value)||30;
   const width=cv.width,height=cv.height;
   const config={codec:'avc1.64002a',width,height,bitrate:width*height>2100000?14000000:9000000,framerate:fps,avc:{format:'avc'}};
   const support=await VideoEncoder.isConfigSupported(config);
   if(!support.supported)throw new Error('H.264 encoding is unsupported at this resolution. Try another browser.');
   muxer=new lib.Muxer({target:new lib.ArrayBufferTarget(),video:{codec:'avc',width,height},fastStart:'in-memory',firstTimestampBehavior:'offset'});
   let encodeError=null;
   encoder=new VideoEncoder({output:(chunk,meta)=>muxer.addVideoChunk(chunk,meta),error:e=>{encodeError=e}});
   encoder.configure(config);
   const frames=Math.ceil(state.durations[state.scene]*fps);
   for(let i=0;i<frames;i++){
     if(encodeError)throw encodeError;
     state.t=i/frames;
     renderFrame();
     const frame=new VideoFrame(cv,{timestamp:Math.round(i*1000000/fps),duration:Math.round(1000000/fps)});
     encoder.encode(frame,{keyFrame:i%fps===0});frame.close();
     if(i%8===0){info('Encoding MP4… '+Math.round(i/frames*100)+'%');await new Promise(r=>setTimeout(r,0))}
     if(encoder.encodeQueueSize>8)await encoder.flush();
   }
   await encoder.flush();if(encodeError)throw encodeError;
   muxer.finalize();
   const blob=new Blob([muxer.target.buffer],{type:'video/mp4'});
   download(blob,fileName('mp4'));
   info('MP4 exported · '+(blob.size/1048576).toFixed(1)+' MB');
 }catch(e){console.error(e);info('MP4 export failed: '+e.message+' · WebM export is available.');}
 finally{try{encoder?.close()}catch{}state.recording=false;btn.disabled=false;state.playing=previous.playing;resetClock(previous.t)}
}
document.getElementById('exportMP4').onclick=exportMP4;
window.MotionStudio.exportMP4=exportMP4;
